(window.JUZAPP_SURAH = window.JUZAPP_SURAH || {})[89] = {"meta":{"ar":"الفجر","place":"makkah","ayat":30,"pages":[593,594],"juz":[30,30],"hizb":[60,60],"sajdah":[],"prev":"88:26","next":"90:1"},"pages":[{"p":593,"lines":[{"n":1,"w":[["إِلَّا",88,23,0],["مَن",88,23,0],["تَوَلَّىٰ",88,23,0],["وَكَفَرَ",88,23,0],["٢٣",88,23,1],["فَيُعَذِّبُهُ",88,24,0],["ٱللَّهُ",88,24,0],["ٱلۡعَذَابَ",88,24,0],["ٱلۡأَكۡبَرَ",88,24,0],["٢٤",88,24,1]]},{"n":2,"w":[["إِنَّ",88,25,0],["إِلَيۡنَآ",88,25,0],["إِيَابَهُمۡ",88,25,0],["٢٥",88,25,1],["ثُمَّ",88,26,0],["إِنَّ",88,26,0],["عَلَيۡنَا",88,26,0],["حِسَابَهُم",88,26,0],["٢٦",88,26,1]]},{"n":5,"w":[["وَٱلۡفَجۡرِ",89,1,0],["١",89,1,1],["وَلَيَالٍ",89,2,0],["عَشۡرٖ",89,2,0],["٢",89,2,1],["وَٱلشَّفۡعِ",89,3,0],["وَٱلۡوَتۡرِ",89,3,0],["٣",89,3,1],["وَٱلَّيۡلِ",89,4,0],["إِذَا",89,4,0],["يَسۡرِ",89,4,0],["٤",89,4,1]]},{"n":6,"w":[["هَلۡ",89,5,0],["فِي",89,5,0],["ذَٰلِكَ",89,5,0],["قَسَمٞ",89,5,0],["لِّذِي",89,5,0],["حِجۡرٍ",89,5,0],["٥",89,5,1],["أَلَمۡ",89,6,0],["تَرَ",89,6,0],["كَيۡفَ",89,6,0],["فَعَلَ",89,6,0],["رَبُّكَ",89,6,0],["بِعَادٍ",89,6,0],["٦",89,6,1]]},{"n":7,"w":[["إِرَمَ",89,7,0],["ذَاتِ",89,7,0],["ٱلۡعِمَادِ",89,7,0],["٧",89,7,1],["ٱلَّتِي",89,8,0],["لَمۡ",89,8,0],["يُخۡلَقۡ",89,8,0],["مِثۡلُهَا",89,8,0],["فِي",89,8,0],["ٱلۡبِلَٰدِ",89,8,0],["٨",89,8,1],["وَثَمُودَ",89,9,0],["ٱلَّذِينَ",89,9,0]]},{"n":8,"w":[["جَابُواْ",89,9,0],["ٱلصَّخۡرَ",89,9,0],["بِٱلۡوَادِ",89,9,0],["٩",89,9,1],["وَفِرۡعَوۡنَ",89,10,0],["ذِي",89,10,0],["ٱلۡأَوۡتَادِ",89,10,0],["١٠",89,10,1],["ٱلَّذِينَ",89,11,0],["طَغَوۡاْ",89,11,0],["فِي",89,11,0]]},{"n":9,"w":[["ٱلۡبِلَٰدِ",89,11,0],["١١",89,11,1],["فَأَكۡثَرُواْ",89,12,0],["فِيهَا",89,12,0],["ٱلۡفَسَادَ",89,12,0],["١٢",89,12,1],["فَصَبَّ",89,13,0],["عَلَيۡهِمۡ",89,13,0],["رَبُّكَ",89,13,0],["سَوۡطَ",89,13,0]]},{"n":10,"w":[["عَذَابٍ",89,13,0],["١٣",89,13,1],["إِنَّ",89,14,0],["رَبَّكَ",89,14,0],["لَبِٱلۡمِرۡصَادِ",89,14,0],["١٤",89,14,1],["فَأَمَّا",89,15,0],["ٱلۡإِنسَٰنُ",89,15,0],["إِذَا",89,15,0],["مَا",89,15,0],["ٱبۡتَلَىٰهُ",89,15,0]]},{"n":11,"w":[["رَبُّهُۥ",89,15,0],["فَأَكۡرَمَهُۥ",89,15,0],["وَنَعَّمَهُۥ",89,15,0],["فَيَقُولُ",89,15,0],["رَبِّيٓ",89,15,0],["أَكۡرَمَنِ",89,15,0],["١٥",89,15,1],["وَأَمَّآ",89,16,0],["إِذَا",89,16,0],["مَا",89,16,0],["ٱبۡتَلَىٰهُ",89,16,0]]},{"n":12,"w":[["فَقَدَرَ",89,16,0],["عَلَيۡهِ",89,16,0],["رِزۡقَهُۥ",89,16,0],["فَيَقُولُ",89,16,0],["رَبِّيٓ",89,16,0],["أَهَٰنَنِ",89,16,0],["١٦",89,16,1],["كـَلَّاۖ",89,17,0],["بَل",89,17,0],["لَّا",89,17,0],["تُكۡرِمُونَ",89,17,0]]},{"n":13,"w":[["ٱلۡيَتِيمَ",89,17,0],["١٧",89,17,1],["وَلَا",89,18,0],["تَحَٰٓضُّونَ",89,18,0],["عَلَىٰ",89,18,0],["طَعَامِ",89,18,0],["ٱلۡمِسۡكِينِ",89,18,0],["١٨",89,18,1],["وَتَأۡكُلُونَ",89,19,0]]},{"n":14,"w":[["ٱلتُّرَاثَ",89,19,0],["أَكۡلٗا",89,19,0],["لَّمّٗا",89,19,0],["١٩",89,19,1],["وَتُحِبُّونَ",89,20,0],["ٱلۡمَالَ",89,20,0],["حُبّٗا",89,20,0],["جَمّٗا",89,20,0],["٢٠",89,20,1],["كـَلَّآۖ",89,21,0],["إِذَا",89,21,0]]},{"n":15,"w":[["دُكَّتِ",89,21,0],["ٱلۡأَرۡضُ",89,21,0],["دَكّٗا",89,21,0],["دَكّٗا",89,21,0],["٢١",89,21,1],["وَجَآءَ",89,22,0],["رَبُّكَ",89,22,0],["وَٱلۡمَلَكُ",89,22,0],["صَفّٗا",89,22,0],["صَفّٗا",89,22,0],["٢٢",89,22,1]]}],"headers":[{"id":89,"ar":"الفجر","en":"Al-Fajr","before":5,"bism":true}],"specials":[{"n":3,"k":"name","ar":"الفجر","s":89},{"n":4,"k":"bism","ar":"الفجر","s":89}]},{"p":594,"lines":[{"n":1,"w":[["وَجِاْيٓءَ",89,23,0],["يَوۡمَئِذِۭ",89,23,0],["بِجَهَنَّمَۚ",89,23,0],["يَوۡمَئِذٖ",89,23,0],["يَتَذَكَّرُ",89,23,0],["ٱلۡإِنسَٰنُ",89,23,0],["وَأَنَّىٰ",89,23,0]]},{"n":2,"w":[["لَهُ",89,23,0],["ٱلذِّكۡرَىٰ",89,23,0],["٢٣",89,23,1],["يَقُولُ",89,24,0],["يَٰلَيۡتَنِي",89,24,0],["قَدَّمۡتُ",89,24,0],["لِحَيَاتِي",89,24,0],["٢٤",89,24,1],["فَيَوۡمَئِذٖ",89,25,0]]},{"n":3,"w":[["لَّا",89,25,0],["يُعَذِّبُ",89,25,0],["عَذَابَهُۥٓ",89,25,0],["أَحَدٞ",89,25,0],["٢٥",89,25,1],["وَلَا",89,26,0],["يُوثِقُ",89,26,0],["وَثَاقَهُۥٓ",89,26,0],["أَحَدٞ",89,26,0],["٢٦",89,26,1],["يَٰٓأَيَّتُهَا",89,27,0]]},{"n":4,"w":[["ٱلنَّفۡسُ",89,27,0],["ٱلۡمُطۡمَئِنَّةُ",89,27,0],["٢٧",89,27,1],["ٱرۡجِعِيٓ",89,28,0],["إِلَىٰ",89,28,0],["رَبِّكِ",89,28,0],["رَاضِيَةٗ",89,28,0],["مَّرۡضِيَّةٗ",89,28,0],["٢٨",89,28,1]]},{"n":5,"w":[["فَٱدۡخُلِي",89,29,0],["فِي",89,29,0],["عِبَٰدِي",89,29,0],["٢٩",89,29,1],["وَٱدۡخُلِي",89,30,0],["جَنَّتِي",89,30,0],["٣٠",89,30,1]]},{"n":8,"w":[["لَآ",90,1,0],["أُقۡسِمُ",90,1,0],["بِهَٰذَا",90,1,0],["ٱلۡبَلَدِ",90,1,0],["١",90,1,1],["وَأَنتَ",90,2,0],["حِلُّۢ",90,2,0],["بِهَٰذَا",90,2,0],["ٱلۡبَلَدِ",90,2,0],["٢",90,2,1],["وَوَالِدٖ",90,3,0],["وَمَا",90,3,0],["وَلَدَ",90,3,0]]},{"n":9,"w":[["٣",90,3,1],["لَقَدۡ",90,4,0],["خَلَقۡنَا",90,4,0],["ٱلۡإِنسَٰنَ",90,4,0],["فِي",90,4,0],["كَبَدٍ",90,4,0],["٤",90,4,1],["أَيَحۡسَبُ",90,5,0],["أَن",90,5,0],["لَّن",90,5,0],["يَقۡدِرَ",90,5,0],["عَلَيۡهِ",90,5,0]]},{"n":10,"w":[["أَحَدٞ",90,5,0],["٥",90,5,1],["يَقُولُ",90,6,0],["أَهۡلَكۡتُ",90,6,0],["مَالٗا",90,6,0],["لُّبَدًا",90,6,0],["٦",90,6,1],["أَيَحۡسَبُ",90,7,0],["أَن",90,7,0],["لَّمۡ",90,7,0],["يَرَهُۥٓ",90,7,0],["أَحَدٌ",90,7,0]]},{"n":11,"w":[["٧",90,7,1],["أَلَمۡ",90,8,0],["نَجۡعَل",90,8,0],["لَّهُۥ",90,8,0],["عَيۡنَيۡنِ",90,8,0],["٨",90,8,1],["وَلِسَانٗا",90,9,0],["وَشَفَتَيۡنِ",90,9,0],["٩",90,9,1],["وَهَدَيۡنَٰهُ",90,10,0]]},{"n":12,"w":[["ٱلنَّجۡدَيۡنِ",90,10,0],["١٠",90,10,1],["فَلَا",90,11,0],["ٱقۡتَحَمَ",90,11,0],["ٱلۡعَقَبَةَ",90,11,0],["١١",90,11,1],["وَمَآ",90,12,0],["أَدۡرَىٰكَ",90,12,0],["مَا",90,12,0],["ٱلۡعَقَبَةُ",90,12,0],["١٢",90,12,1]]},{"n":13,"w":[["فَكُّ",90,13,0],["رَقَبَةٍ",90,13,0],["١٣",90,13,1],["أَوۡ",90,14,0],["إِطۡعَٰمٞ",90,14,0],["فِي",90,14,0],["يَوۡمٖ",90,14,0],["ذِي",90,14,0],["مَسۡغَبَةٖ",90,14,0],["١٤",90,14,1],["يَتِيمٗا",90,15,0],["ذَا",90,15,0],["مَقۡرَبَةٍ",90,15,0]]},{"n":14,"w":[["١٥",90,15,1],["أَوۡ",90,16,0],["مِسۡكِينٗا",90,16,0],["ذَا",90,16,0],["مَتۡرَبَةٖ",90,16,0],["١٦",90,16,1],["ثُمَّ",90,17,0],["كَانَ",90,17,0],["مِنَ",90,17,0],["ٱلَّذِينَ",90,17,0],["ءَامَنُواْ",90,17,0],["وَتَوَاصَوۡاْ",90,17,0]]},{"n":15,"w":[["بِٱلصَّبۡرِ",90,17,0],["وَتَوَاصَوۡاْ",90,17,0],["بِٱلۡمَرۡحَمَةِ",90,17,0],["١٧",90,17,1],["أُوْلَٰٓئِكَ",90,18,0],["أَصۡحَٰبُ",90,18,0],["ٱلۡمَيۡمَنَةِ",90,18,0],["١٨",90,18,1]]}],"headers":[{"id":90,"ar":"البلد","en":"Al-Balad","before":8,"bism":true}],"specials":[{"n":6,"k":"name","ar":"البلد","s":90},{"n":7,"k":"bism","ar":"البلد","s":90}]}],"tr":{"1":"By the dawn","2":"And [by] ten nights","3":"And [by] the even [number] and the odd","4":"And [by] the night when it passes,","5":"Is there [not] in [all] that an oath [sufficient] for one of perception?","6":"Have you not considered how your Lord dealt with ʿAad -","7":"[With] Iram - who had lofty pillars,","8":"The likes of whom had never been created in the land?","9":"And [with] Thamūd, who carved out the rocks in the valley?","10":"And [with] Pharaoh, owner of the stakes?","11":"[All of] whom oppressed within the lands","12":"And increased therein the corruption.","13":"So your Lord poured upon them a scourge of punishment.","14":"Indeed, your Lord is in observation.","15":"And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, \"My Lord has honored me.\"","16":"But when He tries him and restricts his provision, he says, \"My Lord has humiliated me.\"","17":"No! But you do not honor the orphan","18":"And you do not encourage one another to feed the poor.","19":"And you consume inheritance, devouring [it] altogether,","20":"And you love wealth with immense love.","21":"No! When the earth has been leveled - pounded and crushed","22":"And your Lord has come and the angels, rank upon rank,","23":"And brought [within view], that Day, is Hell - that Day, man will remember, but how [i.e., what good] to him will be the remembrance?","24":"He will say, \"Oh, I wish I had sent ahead [some good] for my life.\"","25":"So on that Day, none will punish [as severely] as His punishment,","26":"And none will bind [as severely] as His binding [of the evildoers].","27":"[To the righteous it will be said], \"O reassured soul,","28":"Return to your Lord, well-pleased and pleasing [to Him],","29":"And enter among My [righteous] servants","30":"And enter My Paradise.\""},"edges":{"88:26":{"page":593,"text":"ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم","tr":"Then indeed, upon Us is their account."},"90:1":{"page":594,"text":"لَآ أُقۡسِمُ بِهَٰذَا ٱلۡبَلَدِ","tr":"I swear by this city [i.e., Makkah] –"}},"content":{"n":89,"sub":"Named after al-fajr, “the dawn”, the surah’s opening word","theme":"Allah is always watching. Wealth and poverty are both tests, not signs of honour or disgrace, and on the Day of Judgement only what you sent ahead will count.","story":["Revealed in Makkah, when the persecution of new Muslims had begun. The Makkans refused to accept that deeds would be rewarded and punished in the Hereafter.","So the surah swears by dawn and sacred nights, recalls what happened to ʿĀd, Thamūd and Pharaoh when they spread corruption, and exposes a society that treated wealth as honour, neglected orphans and devoured inheritances.","It ends on the Day when regret is useless, and with Allah’s gentle call to the soul at peace. The Prophet ﷺ named it among the surahs suitable for leading prayer."],"sections":[{"a":1,"b":5,"title":"Allah swears by the dawn and the ten nights","gist":"The surah opens with four oaths on sacred times and on the turning of night into day, then asks whether that is not enough for a man whose mind holds him back from wrong.","meaning":"Allah swears by the dawn, by ten nights, by the even and the odd, and by the night as it passes. Isn’t that oath enough for anyone with sense?","points":[["1–2","By the dawn and ten nights"],["3","By the even and the odd"],["4","By the night as it moves away"],["5","Enough of an oath for one with sense?"]],"matters":"These oaths point to sacred times of worship and to the steady order of night and day. A thinking person should see that the One who runs this order will also hold people to account.","story":"No specific incident. The ten nights are usually taken as the first ten of Dhul-Ḥijjah. The Prophet ﷺ said no days are more beloved to Allah for good deeds than these.","explained":["Al-fajr: the dawn of every day, when night ends and light breaks; or one special dawn, such as that of the Day of Sacrifice. Layālin ʿashr: ten nights, most often the first ten of Dhul-Ḥijjah, or the last ten of Ramaḍān.","Ash-shafʿ wal-watr: the even and the odd. In one report, the Day of Sacrifice and the Day of ʿArafah; others say all creation in pairs, and Allah the One. The night yasr: moving on and leaving. Is that not enough for dhū ḥijr, one whose mind holds him back from wrong?"],"teaches":["Value the dawn and the sacred ten days; Allah swears by them.","Real intelligence is a mind that stops you from wrong.","Reflect on the signs you see every day."],"hook":"Four oaths, each starting with wa: wal-fajr, wa-layālin, wash-shafʿ, wal-layl. Dawn opens (1), night closes (4), then a question (5).","plain":["Allah opens with oaths, and the first is *by the dawn*: the moment light bursts out of the dark, a new day just like the one that ended, and sleepers rise from sleep, a kind of small death, to go out after their living. Every morning is a picture of the dead rising. It may mean every dawn, or one special one, such as the dawn of the Day of Sacrifice.","Then *by ten nights*, most often taken as the first ten nights of Dhul-Ḥijjah, the month of Hajj, or else the last ten of Ramaḍān, which hold the Night of Decree. Either way they are the most honoured nights of the year. Allah is swearing by **times of worship**, and by the worship His humble servants do in them.","Then *by the even and the odd*. The Quran doesn't say which. One report from the Prophet ﷺ makes the odd the Day of ʿArafah, the 9th, and the even the Day of Sacrifice, the 10th. Others read it as all creation, made in pairs, set against Allah, the One with no pair. Then *by the night when it passes*, slipping away until dawn comes again, so the oath circles back to where it began.","Then a question: *is there not in that an oath for one of perception?* The word for perception, *ḥijr*, means a mind that holds a person back from what is beneath him. Anyone with such a mind should see that the One who runs night and day so exactly can bring the Hereafter, and that His wisdom requires a reckoning. What the oaths swear to is left unsaid for the listener to supply: **you will be raised and judged.**"],"point":"Dawn, sacred nights and the passing night show a world run by a wise Lord, and anyone with sense should see that He will call people to account."},{"a":6,"b":14,"title":"Stronger nations than these were lashed for their tyranny","gist":"History comes next. ʿĀd with their pillars, Thamūd carving rock in the valley and Pharaoh with his stakes all filled the land with corruption, and none of it slipped past a Lord who is always watching.","meaning":"Have you not seen what your Lord did to ʿĀd of Iram, with its lofty pillars, unmatched in the land; to Thamūd, who carved rock in the valley; and to Pharaoh of the stakes? They tyrannised and spread corruption, so your Lord poured a whip of punishment on them. He is always watching.","points":[["6–8","ʿĀd of Iram, the pillared, unmatched in the land"],["9","Thamūd, who carved rocks in the valley"],["10","Pharaoh, man of the stakes"],["11–12","They tyrannised and multiplied corruption"],["13–14","A whip of punishment; your Lord lies in wait"]],"matters":"History is the proof. The strongest nations were destroyed once they became tyrants, and ayah 14 is the key line of the surah: your Lord is ever watchful. Nobody slips past.","story":"No specific incident. Persecution of Muslims had begun in Makkah, and the Quraysh were warned with the fate of three nations far stronger than they were.","explained":["ʿĀd, also called Iram, were the earlier ʿĀd, to whom Hūd was sent. Dhāt al-ʿimād: people of tall pillars, either their raised buildings or their tall, powerful bodies. No nation had been created like them in the land. Thamūd carved homes out of the rock in the valley.","Pharaoh was dhū al-awtād, owner of the stakes: either the armies that held up his rule, or the stakes he used to torture people. All of them tyrannised and filled the land with corruption, so Allah poured on them a sawṭ ʿadhāb, a lashing of punishment. Inna rabbaka la-bil-mirṣād: He watches, and nothing escapes Him."],"teaches":["Strength, buildings and armies cannot protect tyrants.","Oppression and corruption bring Allah’s punishment.","Allah gives time, but He is always watching.","Learn from history before becoming its warning."],"hook":"Three nations in order: ʿĀd (6), Thamūd (9), Pharaoh (10), each with one mark: pillars, rocks, stakes. “Your Lord” appears at 6, 13 and 14.","plain":["After the oaths comes history. *Have you not considered how your Lord dealt with ʿĀd?* \"Considered\" means seen with the heart, known as surely as if you had watched it. The Makkans were persecuting the new Muslims, so they are shown three peoples who lived longer and were far stronger than they were, and what happened to them.","ʿĀd, called Iram after an ancestor, were the earlier ʿĀd, to whom the prophet Hūd was sent. They were *of lofty pillars*: either their buildings stood on great pillars, or they were tall as pillars themselves. No people had been made like them in strength and size, and they boasted, \"Who is mightier than us?\" They rejected Hūd, and a furious wind destroyed them.","Next came Thamūd, nearest to ʿĀd in time and most like them, who *carved out the rocks in the valley*, cutting homes into the mountains. Then *Pharaoh, owner of the stakes*: either the armies that held his rule firm as tent pegs, so it seemed it could never fall, or the stakes he drove into the ground to tie down and torture people.","One description fits all three: they *oppressed within the lands and increased therein the corruption*, spreading disbelief, killing, and blocking people from Allah's way. *So your Lord poured upon them a scourge of punishment*, blow after blow, like a whip. Then the line the surah turns on: **your Lord is in observation**, waiting at the lookout on the road everyone must travel. He gives the wrongdoer time, then seizes him."],"point":"The mightiest nations were destroyed once they turned tyrant, because your Lord watches every deed from a lookout no one can slip past."},{"a":15,"b":20,"title":"Money is a test, not a sign of honour","gist":"The lens turns from nations to one man, who reads a full hand as Allah’s favour and an empty one as disgrace. What shows him up is the orphan he ignores and the wealth he never has enough of.","meaning":"When Allah tests man with blessings, he says “My Lord has honoured me”; when He tests him with less, he says “My Lord has humiliated me.” No! The real problem: you don’t honour the orphan, don’t urge feeding the poor, devour inheritance greedily and love wealth too much.","points":[["15","Given plenty: “My Lord has honoured me”"],["16","Given less: “My Lord has humiliated me”"],["17–18","No! You don’t honour orphans or urge feeding the poor"],["19–20","You devour inheritance and love wealth too much"]],"matters":"It corrects a common mistake: judging Allah’s love by money. Wealth and poverty are both tests. What really shows a person’s standing is how he treats the weak and how tightly he clutches his wealth.","story":"Reportedly revealed about Umayyah ibn Khalaf. Qudāmah ibn Maẓʿūn was an orphan in his care, and he kept him from his rights. At the time, women and children were often cut out of inheritance.","explained":["Ibtalāhu: Allah tests man. If He gives honour and comfort, man thinks it proves Allah favours him. If He restricts his provision, he says Allah has disgraced him. Kallā: never. Allah gives wealth to those He loves and those He doesn’t, and withholds from both. The test is gratitude in plenty and patience in hardship.","The real failing is elsewhere. You don’t honour the orphan: not just feeding him, but treating him with dignity. You don’t urge each other to feed the miskīn. You devour inheritance, grabbing everyone’s share, lawful or not. And you love wealth ḥubban jammā, with a love that never has enough."],"teaches":["Wealth is not proof of Allah’s love, and poverty is not proof of His anger.","Be grateful when given, patient when held back.","Honour orphans with respect, not only with money.","Encourage others to feed the poor, even if you have little."],"hook":"Two “when He tests him” lines (15–16) end in opposite words: akraman (honoured me) and ahānan (humiliated me). Kallā answers, and the next words reuse the root: lā tukrimūna al-yatīm (17).","plain":["Allah is watching. So what does He see in an ordinary man? The surah turns from nations to human nature. *When his Lord tries him and is generous to him*, he says, *\"My Lord has honoured me.\"* *When He tries him and restricts his provision*, he says, *\"My Lord has humiliated me.\"* The Makkan disbelievers used exactly this to argue that they must be dearer to Allah than the Muslims, who had so little.","*No!* Both thoughts are wrong. Wealth is not a reward and poverty is not a punishment: **both are tests.** Allah gives wealth to those He loves and those He doesn't, and holds it back from both. What He looks for is gratitude when you have plenty and patience when you have little. Honour with Allah comes from obeying Him; disgrace comes from disobeying Him.","And if you think your money means Allah honoured you, look at how you honour others. *You do not honour the orphan*: you don't meet his needs or treat him with dignity, and you take what his father left him. *You do not encourage one another to feed the poor*, because love of this world has a grip on your hearts. Even someone with nothing to give can urge others to give.","Then the love of wealth seen from inside. *You consume inheritance, devouring it altogether*: your share and everyone else's, lawful mixed with unlawful. Women and young children were given nothing. *And you love wealth with immense love.* Some love of money is natural and is not blamed here. Theirs was the kind that never has enough."],"point":"Wealth and poverty are tests, not verdicts; what shows a person's real standing is how he treats the orphan and the poor, and how greedily he grabs."},{"a":21,"b":30,"title":"He will wish he had sent something ahead","gist":"Wealth is gone by then. The earth is pounded flat, the angels come rank on rank and Hell is dragged near, and when the terror is finished the surah ends gently, calling the settled soul home to its Lord.","meaning":"No! When the earth is pounded flat, your Lord comes with angels in rows, and Hell is brought near, man remembers too late and wishes he had sent good ahead. None punishes like Allah that Day. But the soul at peace hears: return to your Lord, pleased and pleasing; enter My Paradise.","points":[["21–22","The earth crushed flat; your Lord comes, angels in rows"],["23","Hell brought near; man remembers, too late"],["24","“If only I had sent ahead for my life”"],["25–26","None punishes or binds like Him"],["27–28","O soul at peace, return, pleased and pleasing"],["29–30","Enter among My servants, enter My Paradise"]],"matters":"It answers the wealth-lovers of section 3: on that Day wealth is gone and only what you sent ahead remains. And it ends the surah not with fear but with a gentle welcome for the believing soul.","story":"Reportedly ayah 27 came while Abū Bakr sat with the Prophet ﷺ. He said nothing could be better, and was told the angel would say it to him. Other reports link it to ʿUthmān or to Khubayb ibn ʿAdī.","explained":["Kallā: your wealth won’t last. The earth is pounded, dakkan dakkā, again and again until flat. Your Lord comes to judge, in a way only He knows, and the angels come rank upon rank. Hell is brought forward. Man finally remembers, but it is useless now. He cries: if only I had sent ahead for my real life.","That Day no one punishes like Allah, and no one binds like He binds. Then the other voice: yā ayyatuhā an-nafs al-muṭmaʾinnah, O soul at rest with Allah. Return to your Lord, rāḍiyah, pleased with Him, marḍiyyah, pleasing to Him. Enter among My servants. Enter My Paradise. It is said at death and on the Day of Judgement."],"teaches":["Send good deeds ahead now; later regret cannot help.","The real life is the one after this.","A heart at peace with Allah is the goal.","Seek the company of the righteous; Paradise is entered among them."],"hook":"Kallā opens this section (21), as it opened ayah 17. Yawmaʾidhin (“that Day”) comes three times: twice in 23, once in 25. The page turns at ayah 23, as Hell is brought near.","plain":["*No!* Not like this: the orphan neglected, the inheritance swallowed, the money loved. The surah moves from the punishments of this world to the one in the Hereafter. If they shrug off what happened to ʿĀd and Pharaoh, or think their own punishment has been put off, a Day is coming that no one escapes. *The earth is pounded and crushed*, blow after blow, until every mountain and building is levelled.","*And your Lord has come, and the angels, rank upon rank*, surrounding all creation. Allah comes to judge between His servants, in a way only He knows. *And Hell is brought*, led forward by angels for everyone to see. *That Day man will remember* every deed he let slip. *But what good will remembering do him?* Belief and good deeds count only in this world.","So all he has left is a wish: *\"I wish I had sent ahead for my life\"*, the life that really lasts. Even the obedient will wish they had done more. **No one punishes as Allah punishes that Day**, and no one binds as He binds.","Then the other voice. Against the restless soul that swung between \"He honoured me\" and \"He humiliated me\" stands *the reassured soul*: at peace through remembering Allah, certain of His promise, content with His decree, steady in good times and bad. *Return to your Lord, well-pleased and pleasing*: pleased with Him, and He with it. **Enter among My servants, and enter My Paradise.** It is said at death, and again on the Day of Judgement."],"point":"On the Day the earth is levelled, regret is useless and only what you sent ahead counts, while the soul at peace is welcomed home to its Lord."}],"groups":[{"a":1,"b":4,"text":"An oath opens the surah: by the dawn breaking over a finished day, by ten nights, by the even and the odd, by the night as it passes."},{"a":5,"b":5,"text":"A question closes the oath: is there not in the dawn and those nights an oath enough for anyone who has sense?"},{"a":6,"b":8,"text":"Look at what your Lord did to ʿĀd of Iram, the place of lofty pillars, whose like was never created in any land."},{"a":9,"b":10,"text":"After ʿĀd came Thamūd, who cut houses out of rock in the valley, and then Firʿawn of the stakes, whose kingdom seemed fixed forever."},{"a":11,"b":12,"text":"One description gathers ʿĀd, Thamūd and Firʿawn’s armies alike: they crossed every limit in the lands they held, and piled up corruption there."},{"a":13,"b":14,"text":"Tyranny in the land brought the punishment down: your Lord poured a whip of punishment over ʿĀd, Thamūd and Firʿawn. Your Lord stays in watch, and nothing escapes Him."},{"a":15,"b":16,"text":"When Allah gives a man wealth and ease, he says his Lord honoured him; when provision is narrowed, he says his Lord humiliated him. Both are tests."},{"a":17,"b":18,"text":"No: wealth is not Allah’s honouring. Those who call it that do not honour the orphan, and do not urge one another to feed the poor."},{"a":19,"b":20,"text":"Love of wealth also shows from inside a man: inheritance swallowed whole, lawful mixed with unlawful, and money loved with a greedy, endless love."},{"a":21,"b":23,"text":"No: on the Day the earth is pounded flat, your Lord comes with angels rank upon rank, and Hell is brought near, man remembers, far too late."},{"a":24,"b":26,"text":"That too-late remembering turns into one wish: if only I had sent good ahead for my life. On that Day no one punishes or binds as Allah does."},{"a":27,"b":28,"text":"Against that punishment and binding stands the other soul: O soul at peace, return to your Lord, well pleased with Him and pleasing to Him."},{"a":29,"b":30,"text":"The return the soul was called to is then spelled out: enter among My righteous servants, and enter My Paradise."}],"ayat":{"1":{"explain":"Wal-fajr: by the dawn. The daybreak of every day, which shows Allah’s power, or one special dawn, such as the Day of Sacrifice or the first day of Muḥarram.","plain":"The dawn is the end of night and the start of day, when light bursts out of darkness: one of the clearest signs of Allah's power, and the time of a great prayer. Most take it as every dawn. Others name one dawn: that of the Day of Sacrifice, or of the first day of Muḥarram, which begins the Islamic year."},"2":{"explain":"Layālin ʿashr: ten nights. Mostly the first ten of Dhul-Ḥijjah, the best days for good deeds; others say the last ten of Ramaḍān, which hold Laylat al-Qadr.","plain":"Ten nights, most often taken as the first ten of Dhul-Ḥijjah, the month of Hajj, which hold the Day of ʿArafah and many of the rites of pilgrimage. Others say the last ten nights of Ramaḍān, which hold the Night of Decree, better than a thousand months. Either way they are the most honoured nights of the year, filled with worship found at no other time."},"3":{"explain":"Ash-shafʿ wal-watr: the even and the odd. In one report, the Day of Sacrifice and the Day of ʿArafah. Others say creation in pairs and Allah the One, or even and odd prayers.","plain":"The Quran doesn't name them, so explanations differ. One report from the Prophet ﷺ makes the odd the Day of ʿArafah (the 9th of Dhul-Ḥijjah) and the even the Day of Sacrifice (the 10th). Others say the even is all creation, made in pairs like night and day or male and female, and the odd is Allah, the One. Some say the even and odd units of prayer."},"4":{"explain":"Wal-layli idhā yasr: by the night as it moves along and departs. Some read it as the night settling in, bringing rest.","plain":"\"Passes\" means travels on and departs, like someone journeying by night, until dawn takes over; so the oaths that began with dawn come back round to it. Some read it as the night arriving and settling over people, so they rest and grow calm, a mercy from Allah. Either way, night giving way to day shows His power and His kindness."},"5":{"explain":"Is there not in that a qasam, an oath enough, for dhū ḥijr? Ḥijr is the mind, because it holds a person back from what is unworthy of him.","plain":"The question means: surely this is enough. Ḥijr is the mind, from a word for holding back, because a sound mind holds a person back from words and deeds beneath him. To anyone who thinks, these oaths show that the One who runs night and day so exactly will hold people to account. What is sworn to is left unsaid: you will be raised and judged."},"6":{"explain":"Alam tara: have you not seen, with your heart’s eye, what your Lord did to ʿĀd, the people of Hūd, who rejected him and were destroyed by a violent wind?","plain":"\"Have you not considered\" means: have you not seen with your heart, known it as surely as if you had watched. It is said in wonder, to warn the Makkans with peoples who lived longer and were far stronger than they. ʿĀd rejected their prophet Hūd; Allah saved him and those who believed with him, and destroyed the rest with a furious wind."},"7":{"explain":"Iram: the earlier ʿĀd. Dhāt al-ʿimād: of the pillars, either their houses raised on strong pillars or their tall stature. Some speak instead of a pillared city they built.","plain":"Iram names them more exactly: the earlier ʿĀd, called after their ancestor Iram, or Iram was the seat of their kingdom. \"Of lofty pillars\" means either their homes raised on strong pillars or their own height, tall as pillars. A less favoured story makes Iram a jewelled palace-city a king named Shaddād built to rival Paradise, destroyed before he could enter it."},"8":{"explain":"No nation like them had been created in the land, in strength, power and size. They boasted, “Who is stronger than us?” (41:15).","plain":"No people anywhere had been made like them, in strength, power and size of body. Their prophet reminded them that Allah had given them extra stature, but they grew arrogant and said, \"Who is mightier than us in strength?\" Some apply these words to their pillars instead, but \"created\" fits a people better than a building."},"9":{"explain":"Thamūd jābū aṣ-ṣakhr: they cut through the rock in the valley, carving homes out of the mountains with their strength.","plain":"Thamūd came next: nearest to ʿĀd in time and most like them, living in comfort among gardens, springs and palms, and repaying it with disbelief. They \"carved out\" the rock, cutting into it the way a pocket is cut into cloth, and made homes inside the mountains of a valley in Arabia, named as Wādī al-Qurā."},"10":{"explain":"Pharaoh dhū al-awtād, of the stakes: either his armies, which held his rule firm like pegs, or the stakes he tied or nailed people to for torture.","plain":"After the two Arab peoples, a non-Arab tyrant. \"The stakes\" is read two ways: his armies, which held his kingdom firm as pegs hold a tent, so that it seemed it could never fall; or the stakes he drove into the ground to tie down or nail the people he tortured. One report says his own wife, Āsiyah, was tortured that way when she believed."},"11":{"explain":"Alladhīna ṭaghaw: all three nations tyrannised in the lands, harming Allah’s servants in their faith and their lives.","plain":"One description gathers all three, ʿĀd, Thamūd, and Pharaoh with his armies: they crossed every limit in the lands they ruled, acting arrogantly and harming Allah's servants in their faith and their lives. The next ayah says what that harm added up to."},"12":{"explain":"They multiplied fasād: disbelief and every kind of sin, killing, fighting the messengers and blocking people from Allah’s way.","plain":"Corruption means disbelief and every branch of sin that grows from it: killing, fighting the messengers, and blocking people from Allah's way. They didn't just commit it; they spread it until it filled the land. That is what brought the punishment down on them."},"13":{"explain":"Sawṭ ʿadhāb: a whip of punishment. A whip lands again and again, so they suffered punishment of many kinds, poured on them.","plain":"A whip lands again and again, and to the Arabs the lash was the picture of the worst pain, so it stands here for punishment of many kinds poured down on them: drowning, earthquake and the rest. Yet next to what waits in the Hereafter, it was only a whip beside a sword."},"14":{"explain":"La-bil-mirṣād: at the lookout, like one waiting on a narrow pass. Allah watches every deed; He gives the disobedient time, then seizes them.","plain":"The mirṣād is a lookout on a narrow pass every traveller must go through, where someone lies in wait. Allah sees and hears everything, and no one's road avoids Him. He gives the wrongdoer a little time, then seizes him with a grip no one escapes, and repays everyone with justice. Some take this as what the opening oaths swear to."},"15":{"explain":"Tested with honour and comfort, man says: my Lord has honoured me, as if blessings proved Allah’s love for him.","why":"Reportedly revealed about Umayyah ibn Khalaf, a disbeliever of Makkah.","plain":"\"As for man\" turns from those nations to human nature itself. Given wealth, rank and comfort, he assumes it will last and that it proves he is close to Allah, or that he earned it by his own cleverness. But it is called a test: Allah gives in order to see whether he will be grateful."},"16":{"explain":"Tested with limited provision, he says: my Lord has humiliated me. Both conditions are tests, of gratitude and of patience.","plain":"Tested with less, given just enough to get by and nothing spare, he decides Allah has disgraced him. Both reactions measure Allah's love in money. This mostly describes the disbeliever, but a Muslim can fall into the very same thinking."},"17":{"explain":"Kallā: not so! Honour is not measured by wealth. Bal lā tukrimūna al-yatīm: you don’t give the orphan his rights or treat him with dignity.","why":"Reportedly about Qudāmah ibn Maẓʿūn, an orphan raised by Umayyah ibn Khalaf, who kept him from his rights.","plain":"\"No!\" rejects both ideas: Allah does not honour by giving plenty or disgrace by giving little. Pharaoh claimed to be a god and never even had a headache, while some prophets were sawn in two by their enemies. Then \"but\" turns the blame: you think Allah honoured you, yet you don't honour the orphan, who has lost his father and provider."},"18":{"explain":"Lā taḥāḍḍūna: you don’t urge one another to feed the miskīn. Even those with little can encourage others to give.","plain":"You don't urge one another, your families or anyone, to feed the poor, because love of the world grips your hearts. Urging others to give is greater even than giving, since it leads to more giving. The poor man's food is called *his*: he has a share in the rich man's wealth. Even someone with nothing can still encourage others."},"19":{"explain":"At-turāth: inheritance. Aklan lammā: devouring it all together, your share and others’, lawful or not. Women and children were often denied their shares.","plain":"Inheritance is what the dead leave behind. \"Devouring altogether\" means gathering it all in, your own share and others', lawful mixed with unlawful, without asking where it came from. They gave women and young children nothing. Inheritance is singled out because waiting greedily for someone to die shows greed at its ugliest."},"20":{"explain":"Ḥubban jammā: an overflowing love of wealth. Some love of money is natural; what is blamed is excessive love that is never satisfied.","plain":"The word for \"immense\" is used of water gathering and filling a pool: a love of wealth that piles up and never stops. Loving money in moderation is natural and is not blamed here. The blame is for a love so great that this world becomes the limit of a person's whole outlook."},"21":{"explain":"Kallā: stop! Dakkan dakkā: the earth is pounded again and again until every mountain and building is levelled.","plain":"\"No!\" rebukes everything just listed. The surah now moves from punishments in this world, like ʿĀd's, to the punishment of the Hereafter. \"Pounded and crushed\" is repeated because the pounding comes again and again, on every mountain and hill, until all of it is dust and the earth lies flat without a bump."},"22":{"explain":"Your Lord comes to judge between His creation, in a way only He knows, and the angels come ṣaffan ṣaffā, rank after rank.","plain":"\"Your Lord has come\" to judge between His servants, in a way no one but He knows; some explain it as His command and decree coming. It comes after people beg the great messengers one by one to intercede for them, until the Prophet ﷺ agrees. The angels come rank upon rank, those of each heaven in their own row, surrounding all creation."},"23":{"explain":"Hell is brought forward; the Prophet ﷺ said it will have 70,000 reins, each pulled by 70,000 angels. Man remembers his deeds, but what use is remembering now?","plain":"Hell is brought forward, led by angels, so that everyone sees it; a hadith says it will have seventy thousand reins, each pulled by seventy thousand angels. Then man remembers his deeds and everything he neglected. But the question means it will do him no good: belief and good deeds count only in this world."},"24":{"explain":"Yā laytanī qaddamtu li-ḥayātī: if only I had sent good ahead for my life, the lasting life. Even the obedient will wish they had done more.","plain":"Man's regret can only be a wish. \"My life\" is the lasting life, with no death after it: he sees now that it was the life worth working for. Or it means \"during my lifetime\". He knows nothing stopped him from obeying but himself. Even the obedient will wish they had done more."},"25":{"explain":"That Day no one punishes like Allah punishes those who ignored that Day.","plain":"No one punishes like Allah's punishment, for those who ignored that Day and never worked for it. In this world people often fear someone else's punishment more than Allah's; that Day it is plain that nobody's comes close. Another reading gives: no one is punished as that disbeliever is punished."},"26":{"explain":"And no one binds like He binds, with chains and fetters. This is the recompense of the wrongdoers.","plain":"Binding means chains and fetters. A prisoner here is bound so he can't escape or harm himself; there, the wrongdoers are chained together with chains of fire and dragged on their faces through boiling water, then burned in the Fire. No one binds like that. This is the repayment of the wrongdoers."},"27":{"explain":"An-nafs al-muṭmaʾinnah: the soul at rest, calm through remembering Allah, certain of Him and content with His decree.","why":"Reportedly revealed while Abū Bakr sat with the Prophet ﷺ, who told him this would be said to him. Other reports link it to ʿUthmān giving the well of Rūmah, or to Khubayb ibn ʿAdī.","plain":"After the restless soul that swung between \"He honoured me\" and \"He humiliated me\" comes the other kind. The reassured soul is calm through remembering Allah, certain that He is its Lord and His promise is true, content with His decree. It was steady in this world, so now it is safe, with no fear and no grief."},"28":{"explain":"Irjiʿī: return to your Lord, rāḍiyah, pleased with Him and His reward, marḍiyyah, with Him pleased with you. Said at death, and again on the Day of Judgement.","plain":"\"Return\" means going back: to its Lord, His company and His reward. \"Well-pleased\" with Allah and what He gives; \"pleasing\", with Allah pleased with it. It is said to the believer at death and again on the Day of Judgement. A hadith says angels of mercy tell a dying believer's soul to come out, well-pleased and pleasing, to Allah's mercy."},"29":{"explain":"Enter among My servants: first join the righteous, whose company is such a blessing that prophets prayed for it.","plain":"First it joins the company of His righteous servants, then enters Paradise with them. That company is so great a blessing that prophets prayed for it: Sulaymān asked to be admitted among Allah's righteous servants, and Yūsuf to be joined with the righteous. Another reading: enter the bodies of My servants, each soul going back into its body when the dead are raised."},"30":{"explain":"And enter My Paradise. Allah calls it “My Paradise”, an honour showing it is the home of His pleasure.","plain":"Allah calls it \"My Paradise\", a great honour: it holds every lasting comfort, but above all it is the home of His pleasure. The surah that began with dawn breaking out of the night ends here, with the soul at peace welcomed home."}},"know":["The surah came down in Makkah after the persecution of the new Muslims had begun. The Makkans refused to accept that people will be repaid in the Hereafter for what they did.","The surah before, Al-Ghāshiyah, ended: \"to Us is their return, then upon Us is their account.\" This surah sets out the evidence for that return and reckoning.","Dhul-Ḥijjah is the month of Hajj, the pilgrimage to Makkah. Its 9th is the Day of ʿArafah, when pilgrims stand at ʿArafāt, the heart of the Hajj; its 10th is the Day of Sacrifice. The opening oaths are often read as pointing to these days.","ʿĀd and Thamūd were ancient Arab peoples, and Pharaoh a tyrant king who called himself a god. All three were powerful, all three crushed people, and all three were destroyed. The Quran tells their stories often as warnings.","In Arabia before Islam, the heads of families controlled the wealth. Women and young children were often given no share of an inheritance; the men said only those who fought for the tribe deserved it. Orphans were easily robbed."],"ar":{"sections":{"1-5":{"title":"قسمٌ بالفجر والليالي العشر","plain":["تبدأ السورة بقسم: ﴿وَالْفَجْرِ﴾. والفجر آخر الليل وأول النهار، ينفجر فيه الصبح من الظلمة. وفي إدبار الليل وإقبال النهار دلائل على كمال قدرة الله، وأنه وحده المدبّر لكل شيء، وفي الفجر صلاة عظيمة. وفيه صورة للبعث أيضًا: نهار جديد يطلع بعد نهار مضى، ويقوم النائمون من النوم، وهو الموت الأصغر، فينتشرون في طلب معاشهم. والأكثر أنه فجر كل يوم، وقيل: فجر يوم بعينه، كفجر يوم النحر.","ثم ﴿وَلَيَالٍ عَشْرٍ﴾، وأكثر الأقوال أنها عشر ذي الحجة، وقيل: العشر الأواخر من رمضان. وهي ليالٍ فاضلة يقع فيها من العبادات ما لا يقع في غيرها، فالقسم هنا بأوقات العبادة. ثم ﴿وَالشَّفْعِ وَالْوَتْرِ﴾، أي الزوج والفرد، ولم تعيّنهما الآية: رُوي عن النبي ﷺ أن الوتر يوم عرفة والشفع يوم النحر، وقيل: الشفع الخلق كله لأنه أزواج، والوتر هو الله الواحد. ثم ﴿وَالَّيْلِ إِذَا يَسْرِ﴾، أي إذا مضى وذهب حتى يخلفه الفجر، فيعود آخر القسم إلى أوله.","ثم يسأل: ﴿هَلْ فِي ذَلِكَ قَسَمٌ لِذِي حِجْرٍ﴾؟ و«الحِجْر» العقل، سُمّي بذلك لأنه يمنع صاحبه مما لا يليق به، وأصل الحجر المنع. والمعنى: بلى، في هذه الأقسام ما يكفي كل عاقل. ولم يُذكر بعدها ما أُقسم عليه، فقيل: هو قوله بعدُ ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾، وقيل: هو محذوف يدل عليه ما بعده. فالعاقل الذي يرى هذا النظام المحكم في الليل والنهار يعلم أن الذي أقامه قادر على أن يبعث الناس ويحاسبهم."],"point":"الفجر والليالي الفاضلة وتعاقب الليل والنهار دلائل على قدرة الله، تكفي العاقل ليعلم أن الحساب حق.","story":"لم يُذكر لهذا المقطع سبب نزول خاص. والليالي العشر في أكثر الأقوال عشر ذي الحجة، وفي فضل أيامها قال النبي ﷺ: «مَا مِنْ أَيَّامٍ الْعَمَلُ الصَّالِحُ أَحَبُّ إِلَى اللهِ فِيهِنَّ مِنْ هذِهِ الْأَيَّام»، يعني أيام العشر."},"6-14":{"title":"عاد وثمود وفرعون: طغَوا فصُبّ عليهم العذاب","plain":["بعد الأقسام يأتي التاريخ: ﴿أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ﴾، أي ألم تعلم بقلبك وبصيرتك علمًا كأنك تراه. والخطاب للنبي ﷺ، والمراد كل سامع. والمقصود تخويف أهل مكة: فعاد كانت أطول أعمارًا وأشد قوة منهم، فانظروا كيف أهلكها الله.","وعاد هم ﴿إِرَمَ ذَاتِ الْعِمَادِ﴾، أي عاد الأولى، قوم هود عليه السلام. وإرم قيل: اسم جدّهم، وقيل: اسم قبيلتهم أو دار ملكهم. و﴿ذَاتِ الْعِمَادِ﴾ قيل: أهل خيام وأعمدة ينتقلون بها، وقيل: أهل أبنية رفيعة على العُمُد، وقيل: لطول قاماتهم وقوتهم. ولم يُخلق مثلهم في البلاد قوةً وشدةً وعِظَم أجسام، حتى قالوا: ﴿مَنْ أَشَدُّ مِنَّا قُوَّةً﴾.","ثم ثمود، قوم صالح عليه السلام، أقرب الأمم إلى عاد زمانًا وأشبهها بهم. ﴿جَابُوا الصَّخْرَ بِالْوَادِ﴾، أي قطعوا الصخر بقوتهم ونحتوه بيوتًا في وادي القرى. ثم فرعون ﴿ذِي الْأَوْتَادِ﴾: قيل: صاحب الجنود الذين ثبّتوا ملكه كما تثبّت الأوتاد ما يُشدّ بها، وقيل: كان يشدّ من يعذّبه إلى أوتاد يدقّها في الأرض.","ثم وصفٌ يجمع الثلاثة: ﴿الَّذِينَ طَغَوْا فِي الْبِلَادِ﴾، أي تجاوزوا الحدّ في الظلم، فأكثروا فيها الفساد: الكفر والمعاصي والقتل ومحاربة الرسل وصدّ الناس عن سبيل الله. فلما بلغوا ذلك ﴿فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ﴾، أي أنزل عليهم أنواعًا من العذاب. ثم الآية التي يدور عليها المقطع: ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾، يرصد أعمال العباد فلا يفوته منها شيء، يمهل العاصي قليلًا ثم يأخذه."],"point":"قوة الأمم وأبنيتها وجنودها لم تمنعها من عذاب الله لما طغت، لأن ربك يرصد الأعمال ولا يفوته أحد.","story":"لم يُذكر لهذا المقطع سبب نزول خاص. وقد نزلت السورة بمكة حين بدأ أذى المسلمين، فذُكر لأهلها مصير ثلاث أمم كانوا يعرفون أخبارها، أولها عاد التي كانت أطول أعمارًا وأشد قوة منهم."},"15-20":{"title":"الغنى والفقر ابتلاء، لا كرامة ولا إهانة","plain":["تنتقل السورة من الأمم إلى طبيعة الإنسان نفسه. إذا ابتلاه ربه، أي اختبره، فأكرمه بالمال ووسّع عليه، قال: ﴿رَبِّي أَكْرَمَنِ﴾، يظن أن نعمة الدنيا دليل على كرامته عند الله وقربه منه. وإذا ابتلاه فضيّق عليه رزقه قال: ﴿رَبِّي أَهَانَنِ﴾. وكان الكفار يقولون ما يشبه هذا: إنهم أحبّ إلى الله من المسلمين، لأن الله وسّع عليهم في الدنيا وقلّل على الصحابة.","فردّ الله عليه: ﴿كَلَّا﴾، أي ليس الأمر كما يظن. ليس كل من وسّع الله عليه كريمًا عنده، ولا كل من ضيّق عليه مُهانًا. فالله يعطي المال من يحب ومن لا يحب، ويمنعه من يحب ومن لا يحب. والغنى والفقر كلاهما امتحان، ليُرى من يشكر عند السعة ويصبر عند الضيق. وإنما يُكرَم العبد بطاعته ويُهان بمعصيته.","ثم ينتقل اللوم إلى ما يكشف حقيقتهم: ﴿بَلْ لَا تُكْرِمُونَ الْيَتِيمَ﴾. تظنون أن الله أكرمكم بالمال، وأنتم لا تُكرمون اليتيم الذي فقد أباه وكاسبه، بل تدفعونه عن حقه في الميراث. ولا يحثّ بعضكم بعضًا على إطعام المسكين، لشدة حب الدنيا في قلوبكم.","ثم يدل على حب المال بأمر في أنفسهم: ﴿وَتَأْكُلُونَ التُّرَاثَ أَكْلًا لَمًّا﴾، أي تأكلون الميراث أكلًا شديدًا جامعًا، تأخذون نصيبكم ونصيب غيركم، الحلال والحرام، فقد كانوا لا يورّثون النساء ولا الصبيان. ﴿وَتُحِبُّونَ الْمَالَ حُبًّا جَمًّا﴾، أي حبًّا كثيرًا مع حرص وشَرَه، فلا تنفقونه."],"point":"المال ليس ميزان الكرامة عند الله، وحقيقة الإنسان تظهر في معاملته لليتيم والمسكين وفي حرصه على المال.","story":"قيل: نزلت الآيتان الأوليان من هذا المقطع في أمية بن خلف، وقيل في غيره (انظر الآية ١٥). ورُوي أن قدامة بن مظعون كان يتيمًا في حِجر أمية بن خلف، وكان أمية يدفعه عن حقه. وكان أهل الجاهلية لا يورّثون النساء ولا الصبيان."},"21-30":{"title":"يومٌ يتمنى فيه الإنسان لو قدّم لحياته","plain":["﴿كَلَّا﴾ مرة أخرى: ما هكذا ينبغي أن يكون الأمر، فهي زجر عن إهمال اليتيم والمسكين وأكل الميراث وحب المال. وتنتقل السورة من عذاب الدنيا الذي نزل بعاد وثمود وفرعون إلى عذاب الآخرة: فإن استخفّوا بما حلّ بتلك الأمم، أو أُخّر عنهم العذاب في الدنيا، فأمامهم يوم لا مهرب منه. ﴿إِذَا دُكَّتِ الْأَرْضُ دَكًّا دَكًّا﴾، أي زُلزلت مرة بعد مرة حتى يتكسر كل ما عليها من جبل وبناء، وتستوي.","﴿وَجَاءَ رَبُّكَ﴾ لفصل القضاء بين عباده، على الوجه الذي يشاء، وقيل: جاء أمره وقضاؤه. وجاءت الملائكة صفًّا بعد صف، يحيطون بالخلق. ﴿وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ﴾ تقودها الملائكة. عندئذ ﴿يَتَذَكَّرُ الْإِنْسَانُ﴾ ما قدّم وما فرّط فيه، ﴿وَأَنَّى لَهُ الذِّكْرَى﴾، أي من أين تنفعه الذكرى وقد فات وقتها؟","فلا يبقى له إلا التمنّي: ﴿يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي﴾، أي ليتني قدّمت عملًا صالحًا لحياتي الباقية التي لا موت بعدها. ﴿فَيَوْمَئِذٍ لَا يُعَذِّبُ عَذَابَهُ أَحَدٌ﴾، أي لا يعذّب أحدٌ مثل عذاب الله، ولا يوثق أحدٌ مثل وثاقه.","ثم الصوت الآخر. بعد ذكر من كانت همّته الدنيا فاتّهم ربه في غناه وفقره، يُذكر من اطمأنت نفسه إلى الله فسلّم لأمره: ﴿يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾، الساكنة إلى ذكر الله، الموقنة بأنه ربها. ﴿ارْجِعِي إِلَى رَبِّكِ رَاضِيَةً مَرْضِيَّةً﴾: راضية عن الله وعما أكرمها به، والله راضٍ عنها. ثم ﴿فَادْخُلِي فِي عِبَادِي﴾ ﴿وَادْخُلِي جَنَّتِي﴾. قيل: يقال لها ذلك عند الموت، وقيل: يوم القيامة، وقيل: في الحالين."],"point":"في ذلك اليوم لا ينفع الندم، ولا ينفع الإنسانَ إلا ما قدّمه، وتُستقبل النفس المطمئنة بالرضا والجنة.","story":"رُوي أن رجلًا قرأ عند النبي ﷺ ﴿يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ﴾، فقال أبو بكر رضي الله عنه: «ما أحسن هذا يا رسول الله»، فقال النبي ﷺ: «إن الملك يقولها لك يا أبا بكر». ورُوي أنها نزلت في عثمان بن عفان رضي الله عنه حين وقف بئر رومة، وقيل: في خبيب بن عدي الذي صلبه أهل مكة (انظر الآية ٢٧)."}},"ayat":{"1":"قسم بالفجر، وهو انفجار الصبح من ظلمة الليل. والأكثر أنه فجر كل يوم، لما في إدبار الليل وإقبال النهار من دلائل قدرة الله، وفيه صلاة عظيمة. وقيل: فجر يوم بعينه: فجر يوم النحر، أو فجر أول يوم من المحرّم الذي تبدأ به السنة. وقيل: المراد صلاة الفجر نفسها.","2":"الليالي العشر في أكثر الأقوال عشر ذي الحجة، وفي أيامها يوم عرفة وكثير من أعمال الحج. ورُوي عن النبي ﷺ أنه قال في تفسيرها: «عشر الأضحى». وقيل: العشر الأواخر من رمضان، وفيها ليلة القدر التي هي خير من ألف شهر، وقيل: العشر الأول من المحرّم. وجاءت ﴿عَشْرٍ﴾ نكرةً تعظيمًا لفضلها على غيرها.","3":"الشفع الزوج، والوتر الفرد. ولم تعيّنهما الآية، فكثرت الأقوال فيهما. رُوي عن النبي ﷺ أن الوتر يوم عرفة لأنه تاسع ذي الحجة، والشفع يوم النحر لأنه عاشرها، وهذه الرواية أصح إسنادًا من رواية أن المراد الصلاة. وقيل: الشفع الخلق كله، لأن الله خلقه أزواجًا كالليل والنهار والسماء والأرض، والوتر هو الله الواحد. وقيل: الصلاة، منها شفع ومنها وتر.","4":"﴿يَسْرِ﴾ من السُّرى، وهو السير ليلًا. والمعنى: إذا مضى وذهب حتى يخلفه الفجر، فيرجع آخر القسم إلى أوله. وقيل: إذا أقبل وأرخى ظلامه على الناس فيسكنون ويستريحون، رحمةً من الله. وقيل: هي ليلة المزدلفة خاصة. وبعد أن أقسم بالليالي العشر خاصة، أقسم هنا بالليل عامة.","5":"﴿قَسَمٌ﴾ أي ما يُقنع ويكفي. و﴿حِجْرٍ﴾ العقل، وأصل الحجر المنع، لأن العقل يمنع صاحبه مما لا يحلّ ولا يليق به. والاستفهام للتقرير: بلى، في هذه الأقسام مقنع لكل عاقل. ولم يُذكر المقسَم عليه، فقيل: هو قوله ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾، وقيل: محذوف، تقديره: ليُعذَّبنّ الكفار.","6":"﴿أَلَمْ تَرَ﴾ أي ألم تعلم بقلبك وبصيرتك، علمًا كأنك تراه، وفي الاستفهام تعجيب. والخطاب للنبي ﷺ، والمراد كل سامع. وعاد قوم هود عليه السلام، كذّبوه فأنجاه الله ومن آمن معه، وأهلك الباقين بريح شديدة. وكانت أخبارهم مشهورة عند العرب لأن ديارهم كانت في بلاد العرب.","7":"﴿إِرَمَ﴾ هم عاد الأولى. قيل: سُمّوا باسم جدّهم إرم، وقيل: إرم قبيلة من عاد، وقيل: دار ملكهم. و﴿ذَاتِ الْعِمَادِ﴾ قيل: كانوا أهل خيام وأعمدة ينتقلون بها، وقيل: أهل أبنية رفيعة على العُمُد، وقيل: لطول قاماتهم، وقيل: لقوتهم. ورُوي أن إرم مدينة بناها شداد بن عاد من الذهب والفضة، فأُهلك قبل أن يدخلها، والأكثرون على أن المراد القوم لا المدينة.","8":"أي لم يُخلق مثل هذه القبيلة في البلاد قوةً وشدةً وعِظَم أجسام. وهذه نعمة ذكّرهم بها نبيهم هود عليه السلام، فاستكبروا وقالوا: ﴿مَنْ أَشَدُّ مِنَّا قُوَّةً﴾. وقيل: الضمير يعود إلى الأعمدة والأبنية، أي لم يُبنَ مثلها. والأول أظهر، لأن الآية قالت ﴿لَمْ يُخْلَقْ﴾، والخلق يناسب الناس لا البناء.","9":"ثمود قوم صالح عليه السلام، وهم أقرب الأمم إلى عاد زمانًا وأشبهها بهم، أُنعم عليهم بالجنات والعيون والزروع فقابلوا ذلك بالكفر. و﴿جَابُوا الصَّخْرَ﴾ أي قطعوه، ومنه سُمّي جيب القميص لأنه يُقطع. فكانوا ينحتون الجبال بقوتهم ويتخذونها بيوتًا. و﴿بِالْوَادِ﴾ أي وادي القرى.","10":"﴿الْأَوْتَادِ﴾ جمع وَتِد، وهو ما يُدقّ في الأرض ليُشدّ به. وفي معناه قولان: قيل: جنوده الذين ثبّتوا ملكه كما تثبّت الأوتاد ما يُشدّ بها، وقيل: كان يعذّب الناس بأوتاد يشدّ إليها أيديهم وأرجلهم. ورُوي أنه فعل ذلك بامرأته آسية لما أظهرت إيمانها، وبماشطة ابنته.","11":"﴿الَّذِينَ طَغَوْا﴾ وصف يجمع عادًا وثمود وفرعون وجنوده. والطغيان تجاوز الحد في الظلم والعدوان والتجبّر. فقد طغوا في بلاد الله، وآذوا عباد الله في دينهم ودنياهم، ولذلك جاءت الآية التالية تبيّن ما انتهى إليه طغيانهم.","12":"الفساد الذي أكثروه: الكفر وشُعَبه من أنواع المعاصي، والقتل والجَور والأذى، ومحاربة الرسل، وصدّ الناس عن سبيل الله. وقوله ﴿فَأَكْثَرُوا﴾ يدل على أنهم لم يكتفوا بفعله، بل نشروه حتى كثر في الأرض. وبهذا استحقّوا العذاب المذكور بعده.","13":"﴿فَصَبَّ﴾ أي أنزل عليهم وألقى، كأنه شيء يُصبّ صبًّا. و﴿سَوْطَ عَذَابٍ﴾ أي نوع من العذاب، لأن السوط كان عند العرب غاية ما يُعذَّب به، فصار اسمًا لكل عذاب، فأصابهم الإغراق والرجفة وغيرهما. وقيل: شُبّه عذاب الدنيا بالسوط إيذانًا بأنه، إذا قيس بعذاب الآخرة، كالسوط إذا قيس بالسيف.","14":"﴿الْمِرْصَادِ﴾ الطريق، أو المكان الذي يقف فيه الراصد يترقّب من يمرّ. فالله يرصد عمل كل إنسان حتى يجازيه به، ولا يفوته أحد، وهو يسمع ويرى. يمهل العاصي قليلًا ثم يأخذه أخذ عزيز مقتدر. وقيل: هذه الآية هي ما أُقسم عليه في أول السورة.","15":"﴿فَأَمَّا الْإِنْسَانُ﴾ قيل: المراد الكافر، والآيتان تصفان كل من يزن الأمور بالدنيا، وقد يقع في ذلك كثير من المسلمين. وابتلاه أي اختبره، فأكرمه بالمال ووسّع عليه، فيفرح ولا يحمد ربه، ويظن أن هذه النعمة دليل على كرامته عند الله. وقد سمّى الله النعمة ابتلاءً، ليُرى أيشكر صاحبها أم يكفر.","16":"﴿فَقَدَرَ عَلَيْهِ رِزْقَهُ﴾ أي ضيّقه، فأعطاه قدر ما يكفيه لا يفضل منه شيء. فيقول: ﴿رَبِّي أَهَانَنِ﴾، أي أذلّني بالفقر. وهذه صفة من يرى الكرامة والهوان في كثرة الدنيا وقلّتها. أما المؤمن فكرامته عنده أن يوفّقه الله لطاعته، فإن وسّع عليه حمده وشكره.","17":"﴿كَلَّا﴾ ردّ على الظنّين معًا: لا الغنى دليل على الكرامة، ولا الفقر دليل على الهوان. فالله يوسّع على الكافر لا لكرامته، ويضيّق على المؤمن لا لهوانه، وإنما يُكرَم العبد بطاعته ويُهان بمعصيته. ثم تنقل ﴿بَلْ﴾ اللوم إليهم: تظنون أن الله أكرمكم بالمال، وأنتم لا تُكرمون اليتيم، فلا تُحسنون إليه، وتمنعونه حقه من الميراث.","18":"﴿تَحَاضُّونَ﴾ أي لا يحثّ بعضكم بعضًا، ولا تأمرون أهلكم، بإطعام المسكين. والسبب الشحّ وحب الدنيا المتمكّن من القلوب. والحثّ على العطاء أعظم من العطاء، لأنه يقود إليه. وأُضيف الطعام إلى ﴿الْمِسْكِينِ﴾ إشارةً إلى أن له حقًّا في مال الغني. ومن لا يملك ما يعطيه يستطيع أن يحثّ غيره.","19":"﴿التُّرَاثَ﴾ الميراث. و﴿أَكْلًا لَمًّا﴾ أي شديدًا جامعًا، من «لَمَمْتُ الشيء» إذا جمعته: يأكل نصيبه ونصيب غيره، ولا يسأل أحلالٌ هو أم حرام. وكانوا لا يورّثون النساء ولا الصبيان، ويأكلون نصيبهم. وخُصّ الميراث بالذكر لأن التطلّع إلى مال الميت من أوضح علامات الحرص.","20":"﴿جَمًّا﴾ أي كثيرًا، من قولهم: جَمَّ الماء في الحوض إذا كثر واجتمع. فهو حب للمال، حلاله وحرامه، مع حرص وشَرَه، حتى صارت الدنيا غاية نظرهم. وأصل حب المال لا يُذمّ هنا، إنما يُذمّ الحب الكثير الذي لا يشبع، فلا يُنفَق منه شيء.","21":"﴿كَلَّا﴾ أي ما هكذا ينبغي أن يكون الأمر، فهي زجر عن الانكباب على الدنيا وجمعها، لأن من فعل ذلك يندم يوم تُدكّ الأرض ولا ينفعه الندم. و﴿دَكًّا دَكًّا﴾ أي مرة بعد مرة، تُزلزل حتى يتكسر كل ما عليها من جبل وبناء وشجر، وتستوي فلا يبقى فيها ارتفاع ولا انخفاض.","22":"يأتي الله تعالى يوم القيامة لفصل القضاء بين عباده، على الوجه الذي يشاء، ولا يعلم كيفية مجيئه إلا هو. وقيل: المراد مجيء أمره وقضائه. ويكون ذلك بعد أن يطلب الناس الشفاعة من الرسل واحدًا بعد واحد، حتى يشفع النبي ﷺ. ﴿وَالْمَلَكُ﴾ أي الملائكة، ﴿صَفًّا صَفًّا﴾ أي صفًّا بعد صف، أهل كل سماء صفّ، يحيطون بمن دونهم من الخلق.","23":"يؤتى بجهنم تقودها الملائكة. وفي الحديث: «يُؤْتَى بِجَهَنَّمَ يَوْمَئِذٍ لَهَا سَبْعُونَ أَلْفَ زِمَامٍ مَعَ كُلِّ زِمَام سَبْعُونَ أَلْفَ مَلَكٍ يَجُرُّونَهَا». حينئذ يتذكّر الإنسان ما قدّم وما فرّط فيه. و﴿وَأَنَّى لَهُ الذِّكْرَى﴾ استفهام بمعنى النفي: لا تنفعه الذكرى، فقد فات أوانها، والإيمان والعمل لا ينفعان إلا في الدنيا.","24":"لا يملك الإنسان يومئذ إلا التمنّي. و﴿لِحَيَاتِي﴾ أي لحياتي الباقية التي لا موت بعدها، فهي الحياة التي تستحق السعي. وقيل: في أيام حياتي في الدنيا. والعاصي يندم على معاصيه، والمطيع يتمنى لو زاد في طاعته. ولعل سبب ندمه علمه أنه كان قادرًا على الطاعة، لا يمنعه منها إلا صرف نفسه عنها.","25":"﴿عَذَابَهُ﴾ أي عذاب الله: لا يعذّب أحدٌ مثل عذاب الله يومئذ لمن أهمل ذلك اليوم ونسي العمل له. وفي الدنيا قد يظن الناس أن عذاب من يخشونه أعظم من عذاب الله، أما يومئذ فلا يقدر أحد على مثله. وفي قراءة بفتح الذال: «لا يُعذَّب»، أي لا يُعذَّب أحدٌ مثل عذاب هذا الكافر.","26":"﴿وَثَاقَهُ﴾ الوثاق: الشدّ بالسلاسل والأغلال. فلا يوثق أحدٌ كما يوثق الله أهل النار: يُقرنون بسلاسل من نار، ويُسحبون على وجوههم في الحميم، ثم في النار يُسجرون. وفي الدنيا يُوثق المعذَّب لئلا يهرب، أما هناك فلا يبلغ أحد وثاقَ الله. وهذا جزاء المجرمين.","27":"بعد ذكر من كانت همّته الدنيا فاتّهم ربه في غناه وفقره، يُذكر من اطمأنت نفسه إلى الله فسلّم لأمره. و﴿الْمُطْمَئِنَّةُ﴾ الساكنة إلى ذكر الله، الموقنة بأنه ربها، المصدّقة بوعده، الراضية بقضائه، الآمنة من عذابه. وهي عامة في كل نفس مؤمنة مخلصة، لا خوف عليها يومئذ ولا حزن، لأنها كانت ثابتة في الدنيا.","28":"﴿ارْجِعِي إِلَى رَبِّكِ﴾ أي إلى ثوابه وكرامته وما أعدّ لعباده. و﴿رَاضِيَةً﴾ عن الله وعما أعطاها، و﴿مَرْضِيَّةً﴾ قد رضي الله عنها. واختُلف متى يقال لها ذلك: قيل عند الموت، وقيل عند البعث، ومعناه حينئذ: ارجعي إلى جسدك، وقيل: في الحالين. ورُوي أن ملكين يأتيان المؤمن عند موته فيقولان لنفسه: «اخرجي أيتها النفس المطمئنة راضية مرضية».","29":"﴿فِي عِبَادِي﴾ أي في جملة عبادي الصالحين، فتنتظم النفس في سلكهم، ثم تدخل الجنة معهم. وصحبة الصالحين نعمة عظيمة دعا بها الأنبياء، كقول سليمان عليه السلام: ﴿وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ﴾. وقيل: المعنى ادخلي في أجساد عبادي، فترجع كل روح إلى جسدها يوم البعث.","30":"﴿جَنَّتِي﴾ أضاف الله الجنة إلى نفسه تشريفًا لها: فهي دار كل نعيم باقٍ، وفوق ذلك دار رضاه. فتدخلها النفس المطمئنة مع عباد الله الصالحين. ورُوي أنه لما دُفن ابن عباس رضي الله عنهما تُليت هذه الآيات على شفير قبره، ولم يُدرَ من تلاها."},"why":{"15":"قيل: نزلت في أمية بن خلف الجمحي، وكان كافرًا. وقيل: في عتبة بن ربيعة وأبي حذيفة بن المغيرة، وقيل: في أُبيّ بن خلف. والمراد بها مع ذلك جنس الكافر الذي يرى الكرامة في كثرة المال والهوان في قلته.","17":"قيل: نزلت في قدامة بن مظعون، وكان يتيمًا في حِجر أمية بن خلف، وكان أمية يدفعه عن حقه.","27":"رُوي أن رجلًا قرأ هذه الآية عند النبي ﷺ، فقال أبو بكر رضي الله عنه: «ما أحسن هذا يا رسول الله»، فقال ﷺ: «إن الملك يقولها لك يا أبا بكر»، وفي رواية أنها نزلت وأبو بكر جالس عنده. ورُوي أنها نزلت في عثمان بن عفان رضي الله عنه حين وقف بئر رومة، وقيل: في خبيب بن عدي الذي صلبه أهل مكة. والأصح أنها عامة في كل نفس مؤمنة."},"theme":"تُقسم السورة بأوقات عظيمة على أن الله يرصد أعمال العباد ويجازيهم عليها، وتذكّر بما فعل بعاد وثمود وفرعون. ثم تبيّن أن الغنى والفقر ابتلاء، لا علامة كرامة ولا إهانة، وتختم بيوم لا ينفع فيه الندم، وبنداء كريم للنفس المطمئنة.","know":["نزلت السورة بمكة حين بدأ أذى المشركين للمسلمين. وكان أهل مكة ينكرون أن الناس يُجازَون في الآخرة على أعمالهم. وختمت السورة التي قبلها، الغاشية، بقوله: ﴿إِنَّ إِلَيْنَا إِيَابَهُمْ﴾، وهذه السورة تأتي بالدليل على هذا الرجوع والحساب.","ذو الحجة شهر الحج. يومه التاسع يوم عرفة، والعاشر يوم النحر. وكثير من الأقسام في أول السورة فُسّرت بهذه الأيام وما فيها من العبادة.","عاد قوم هود عليه السلام، وثمود قوم صالح عليه السلام. وكانت ديارهم في بلاد العرب، وأخبارهم مشهورة عندهم، وديار ثمود باقية تُرى. أما فرعون فكانوا يسمعون خبره من جيرانهم من أهل الكتاب.","كان أهل الجاهلية لا يورّثون النساء ولا الصبيان، ويقولون: لا يستحق المال إلا من يقاتل ويحمي القبيلة. وكانت الأموال يتداولها رؤساء العائلات، فيضيع حق اليتيم بسهولة.","تبدأ السورة بأقسام لا يُذكر بعدها صراحةً ما أُقسم عليه. فقيل: هو قوله بعدُ ﴿إِنَّ رَبَّكَ لَبِالْمِرْصَادِ﴾، وقيل: هو محذوف يدل عليه ما بعده، أي: ليُعذَّبنّ الكفار، أو: ليُبعثُنّ وليُحاسَبُنّ."],"full":true}},"repeats":[],"similars":[{"id":"g1","kind":"cross","more":0,"flow":"Al-Ḥāqqah and Al-Māʿūn say wa-lā yaḥuḍḍu ('he does not encourage'). Al-Fajr alone says wa-lā taḥāḍḍūna ('you do not encourage one another'), because the ayat around it speak to 'you': you do not honor the orphan, you consume inheritance. Al-Māʿūn also has an orphan just before, but there it is 'the one who drives away', one person, so yaḥuḍḍu.","members":[{"k":"69:34","page":567,"exact":false,"diff":[1],"name":"Al-Haqqah","text":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","tr":"Nor did he encourage the feeding of the poor.","cue":"Wa-lā yaḥuḍḍu, about 'he': after he did not believe in Allāh, the Most Great.","before":{"k":"69:33","text":"إِنَّهُۥ كَانَ لَا يُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِيمِ","tr":"Indeed, he did not used to believe in Allāh, the Most Great,"},"after":{"k":"69:35","text":"فَلَيۡسَ لَهُ ٱلۡيَوۡمَ هَٰهُنَا حَمِيمٞ","tr":"So there is not for him here this Day any devoted friend"}},{"k":"89:18","page":593,"exact":true,"diff":[],"name":"Al-Fajr","text":"وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","tr":"And you do not encourage one another to feed the poor.","cue":"Wa-lā taḥāḍḍūna: between 'you do not honor the orphan' and 'you consume inheritance'.","before":{"k":"89:17","text":"كـَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ","tr":"No! But you do not honor the orphan"},"after":{"k":"89:19","text":"وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلٗا لَّمّٗا","tr":"And you consume inheritance, devouring [it] altogether,"}},{"k":"107:3","page":602,"exact":false,"diff":[1],"name":"Al-Ma'un","text":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ","tr":"And does not encourage the feeding of the poor.","cue":"Wa-lā yaḥuḍḍu: after 'the one who drives away the orphan'; next, woe to those who pray.","before":{"k":"107:2","text":"فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ","tr":"For that is the one who drives away the orphan"},"after":{"k":"107:4","text":"فَوَيۡلٞ لِّلۡمُصَلِّينَ","tr":"So woe to those who pray"}}]}]};
